1	import { useState, useCallback } from "react";
2	import { GripVertical } from "lucide-react";
3	
4	// ─── Types ───────────────────────────────────────────────────────────────────
5	
6	export interface KanbanCandidate {
7	  id: string;
8	  name: string;
9	  score: number;
10	  stage: string;
11	  email?: string | null;
12	}
13	
14	interface KanbanCardProps {
15	  candidate: KanbanCandidate;
16	  stages: string[];
17	  onDragStart: (e: React.DragEvent, candidateId: string) => void;
18	  onStageChange: (candidateId: string, newStage: string) => void;
19	}
20	
21	interface KanbanColumnProps {
22	  stage: string;
23	  stages: string[];
24	  candidates: KanbanCandidate[];
25	  onDragStart: (e: React.DragEvent, candidateId: string) => void;
26	  onDragOver: (e: React.DragEvent, stage: string) => void;
27	  onDragLeave: () => void;
28	  onDrop: (e: React.DragEvent, stage: string) => void;
29	  onStageChange: (candidateId: string, newStage: string) => void;
30	  isDragOver: boolean;
31	}
32	
33	interface KanbanBoardProps {
34	  jobId: string;
35	  candidates: KanbanCandidate[];
36	  onStageChange: (candidateId: string, newStage: string) => void;
37	  stages: string[];
38	}
39	
40	// ─── Stage Styling ───────────────────────────────────────────────────────────
41	
42	const STAGE_CONFIG: Record<
43	  string,
44	  { label: string; header: string; card: string; badge: string }
45	> = {
46	  applied: {
47	    label: "Applied",
48	    header:
49	      "bg-slate-100 text-slate-700 dark:bg-slate-800/60 dark:text-slate-300",
50	    card: "border-slate-200 dark:border-slate-700",
51	    badge:
52	      "bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400",
53	  },
54	  screened: {
55	    label: "Screened",
56	    header:
57	      "bg-blue-100 text-blue-700 dark:bg-blue-900/40 dark:text-blue-300",
58	    card: "border-blue-200 dark:border-blue-800",
59	    badge:
60	      "bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400",
61	  },
62	  interview: {
63	    label: "Interview",
64	    header:
65	      "bg-violet-100 text-violet-700 dark:bg-violet-900/40 dark:text-violet-300",
66	    card: "border-violet-200 dark:border-violet-800",
67	    badge:
68	      "bg-violet-100 text-violet-600 dark:bg-violet-900/30 dark:text-violet-400",
69	  },
70	  offer: {
71	    label: "Offer",
72	    header:
73	      "bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300",
74	    card: "border-amber-200 dark:border-amber-800",
75	    badge:
76	      "bg-amber-100 text-amber-600 dark:bg-amber-900/30 dark:text-amber-400",
77	  },
78	  hired: {
79	    label: "Hired",
80	    header:
81	      "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-300",
82	    card: "border-emerald-200 dark:border-emerald-800",
83	    badge:
84	      "bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400",
85	  },
86	  rejected: {
87	    label: "Rejected",
88	    header:
89	      "bg-red-100 text-red-700 dark:bg-red-900/40 dark:text-red-300",
90	    card: "border-red-200 dark:border-red-800",
91	    badge:
92	      "bg-red-100 text-red-600 dark:bg-red-900/30 dark:text-red-400",
93	  },
94	};
95	
96	function getStageConfig(stage: string) {
97	  return (
98	    STAGE_CONFIG[stage] ?? {
99	      label: stage.charAt(0).toUpperCase() + stage.slice(1),
100	      header: "bg-muted text-muted-foreground",
101	      card: "border-border",
102	      badge: "bg-muted text-muted-foreground",
103	    }
104	  );
105	}
106	
107	function getScoreColor(score: number): string {
108	  if (score >= 80) return "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400";
109	  if (score >= 60) return "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400";
110	  return "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400";
111	}
112	
113	// ─── KanbanCard ──────────────────────────────────────────────────────────────
114	
115	function KanbanCard({ candidate, stages, onDragStart, onStageChange }: KanbanCardProps) {
116	  const scoreColor = getScoreColor(candidate.score);
117	
118	  return (
119	    <div
120	      draggable
121	      onDragStart={(e) => onDragStart(e, candidate.id)}
122	      className="group bg-card border border-border rounded-md px-3 py-2.5 cursor-grab active:cursor-grabbing shadow-sm hover:shadow-md transition-shadow duration-150 select-none"
123	    >
124	      <div className="flex items-start gap-2">
125	        <GripVertical className="hidden md:block h-4 w-4 text-muted-foreground/40 group-hover:text-muted-foreground/70 shrink-0 mt-0.5 transition-colors" />
126	        <div className="flex-1 min-w-0">
127	          <p className="text-sm font-semibold text-foreground truncate leading-tight">
128	            {candidate.name}
129	          </p>
130	          {candidate.email && (
131	            <p className="text-[11px] text-muted-foreground truncate mt-0.5">
132	              {candidate.email}
133	            </p>
134	          )}
135	          <select
136	            className="md:hidden text-xs border border-border rounded px-1 py-0.5 mt-1 w-full bg-background text-foreground"
137	            value={candidate.stage}
138	            onChange={(e) => onStageChange(candidate.id, e.target.value)}
139	            onClick={(e) => e.stopPropagation()}
140	          >
141	            {stages.map((s) => (
142	              <option key={s} value={s}>
143	                {STAGE_CONFIG[s]?.label ?? s.charAt(0).toUpperCase() + s.slice(1)}
144	              </option>
145	            ))}
146	          </select>
147	        </div>
148	        {candidate.score > 0 && (
149	          <span
150	            className={`shrink-0 text-[11px] font-semibold px-1.5 py-0.5 rounded ${scoreColor}`}
151	          >
152	            {Math.round(candidate.score)}%
153	          </span>
154	        )}
155	      </div>
156	    </div>
157	  );
158	}
159	
160	// ─── KanbanColumn ─────────────────────────────────────────────────────────────
161	
162	function KanbanColumn({
163	  stage,
164	  stages,
165	  candidates,
166	  onDragStart,
167	  onDragOver,
168	  onDragLeave,
169	  onDrop,
170	  onStageChange,
171	  isDragOver,
172	}: KanbanColumnProps) {
173	  const config = getStageConfig(stage);
174	
175	  return (
176	    <div className="flex flex-col min-w-[220px] w-[220px] shrink-0">
177	      {/* Column header */}
178	      <div
179	        className={`flex items-center justify-between px-3 py-2 rounded-t-lg ${config.header}`}
180	      >
181	        <span className="text-xs font-semibold uppercase tracking-wide">
182	          {config.label}
183	        </span>
184	        <span
185	          className={`text-[11px] font-semibold px-1.5 py-0.5 rounded-full ${config.badge}`}
186	        >
187	          {candidates.length}
188	        </span>
189	      </div>
190	
191	      {/* Drop zone */}
192	      <div
193	        className={`flex-1 min-h-[120px] rounded-b-lg border border-t-0 transition-all duration-150 ${config.card} ${
194	          isDragOver
195	            ? "border-dashed border-2 bg-primary/5 scale-[1.01]"
196	            : "bg-muted/20"
197	        }`}
198	        onDragOver={(e) => onDragOver(e, stage)}
199	        onDragLeave={onDragLeave}
200	        onDrop={(e) => onDrop(e, stage)}
201	      >
202	        <div className="p-2 space-y-2">
203	          {candidates.length === 0 ? (
204	            <p className="text-[11px] text-muted-foreground text-center py-4 italic">
205	              No candidates
206	            </p>
207	          ) : (
208	            candidates.map((candidate) => (
209	              <KanbanCard
210	                key={candidate.id}
211	                candidate={candidate}
212	                stages={stages}
213	                onDragStart={onDragStart}
214	                onStageChange={onStageChange}
215	              />
216	            ))
217	          )}
218	        </div>
219	      </div>
220	    </div>
221	  );
222	}
223	
224	// ─── KanbanBoard ─────────────────────────────────────────────────────────────
225	
226	export default function KanbanBoard({
227	  candidates,
228	  onStageChange,
229	  stages,
230	}: KanbanBoardProps) {
231	  const [dragOverColumn, setDragOverColumn] = useState<string | null>(null);
232	  const [draggingId, setDraggingId] = useState<string | null>(null);
233	
234	  const handleDragStart = useCallback(
235	    (e: React.DragEvent, candidateId: string) => {
236	      setDraggingId(candidateId);
237	      e.dataTransfer.effectAllowed = "move";
238	      e.dataTransfer.setData("candidateId", candidateId);
239	    },
240	    []
241	  );
242	
243	  const handleDragOver = useCallback(
244	    (e: React.DragEvent, stage: string) => {
245	      e.preventDefault();
246	      e.dataTransfer.dropEffect = "move";
247	      setDragOverColumn(stage);
248	    },
249	    []
250	  );
251	
252	  const handleDragLeave = useCallback(() => {
253	    setDragOverColumn(null);
254	  }, []);
255	
256	  const handleDrop = useCallback(
257	    (e: React.DragEvent, targetStage: string) => {
258	      e.preventDefault();
259	      setDragOverColumn(null);
260	      const candidateId = e.dataTransfer.getData("candidateId");
261	      if (!candidateId) return;
262	
263	      const candidate = candidates.find((c) => c.id === candidateId);
264	      if (!candidate) return;
265	      if (candidate.stage === targetStage) return;
266	
267	      onStageChange(candidateId, targetStage);
268	      setDraggingId(null);
269	    },
270	    [candidates, onStageChange]
271	  );
272	
273	  // Group candidates by stage
274	  const grouped = stages.reduce<Record<string, KanbanCandidate[]>>(
275	    (acc, stage) => {
276	      acc[stage] = candidates.filter((c) => c.stage === stage);
277	      return acc;
278	    },
279	    {}
280	  );
281	
282	  // Candidates whose stage doesn't match any known column fall into "applied"
283	  const knownStages = new Set(stages);
284	  candidates.forEach((c) => {
285	    if (!knownStages.has(c.stage)) {
286	      grouped["applied"] = [...(grouped["applied"] ?? []), c];
287	    }
288	  });
289	
290	  return (
291	    <div
292	      className="overflow-x-auto pb-4"
293	      onDragEnd={() => {
294	        setDragOverColumn(null);
295	        setDraggingId(null);
296	      }}
297	    >
298	      <div className="flex gap-3 min-w-max">
299	        {stages.map((stage) => (
300	          <KanbanColumn
301	            key={stage}
302	            stage={stage}
303	            stages={stages}
304	            candidates={grouped[stage] ?? []}
305	            onDragStart={handleDragStart}
306	            onDragOver={handleDragOver}
307	            onDragLeave={handleDragLeave}
308	            onDrop={handleDrop}
309	            onStageChange={onStageChange}
310	            isDragOver={dragOverColumn === stage && draggingId !== null}
311	          />
312	        ))}
313	      </div>
314	    </div>
315	  );
316	}
