25	
26	interface CandidateDetailSheetProps {
27	  result: Result | null;
28	  isOpen: boolean;
29	  onClose: () => void;
30	  jobId?: string | null;
31	  jobTitle?: string | null;
32	  formatCandidateName: (filename: string) => string;
33	  onDownload: (filePath: string, filename: string) => void;
34	  onDismiss: (resumeId: string) => void;
35	  currentStage?: HiringStage | null;
