37	  onStageChange?: (resumeId: string, stage: HiringStage) => void;
38	}
39	
40	const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
41	  if (score >= 70) return { label: "Strong", variant: "success" };
42	  if (score >= 40) return { label: "Good", variant: "warning" };
43	  return { label: "Weak", variant: "destructive" };
44	};
45	
46	const CandidateDetailSheet = ({
47	  result: r,
48	  isOpen,
49	  onClose,
50	  jobId,
51	  jobTitle,
52	  formatCandidateName,
53	  onDownload,
54	  onDismiss,
55	  currentStage,
56	  stageUpdatedAt,
57	  onStageChange,
58	}: CandidateDetailSheetProps) => {
59	  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
60	
61	  if (!r) return null;
62	
63	  const strength = getStrengthLabel(r.overall_score);
64	  const linkedinUrl = extractLinkedInUrl(r);
65	  const candidateName = r.candidate_name || formatCandidateName(r.filename);
66	
67	  return (
68	    <>
69	      <Sheet open={isOpen} onOpenChange={(open) => { if (!open) onClose(); }}>
70	        <SheetContent side="right" className="sm:max-w-2xl w-full p-0 flex flex-col gap-0 [&>button]:hidden">
71	          {/* Dark hero header */}
72	          <div className="bg-foreground text-background px-6 pt-6 pb-5 shrink-0 relative">
73	            <button onClick={onClose} className="absolute top-4 right-4 rounded-sm opacity-70 hover:opacity-100 transition-opacity">
74	              <X className="h-4 w-4" />
75	            </button>
76	
77	            <div className="space-y-3">
78	              <div>
79	                <h2 className="text-xl font-semibold truncate pr-8">{candidateName}</h2>
80	                <div className="flex items-center gap-2 mt-1 flex-wrap text-background/60">
81	                  {r.candidate_location && (
82	                    <span className="flex items-center gap-1 text-xs">
83	                      <MapPin className="h-3 w-3" /> {r.candidate_location}
84	                    </span>
85	                  )}
86	                  {r.candidate_email && <span className="text-xs">{r.candidate_email}</span>}
87	                </div>
88	              </div>
89	
90	              {/* Score + badge row */}
91	              <div className="flex items-end gap-4">
92	                <div>
93	                  <span className="text-xs text-background/50 block">Overall Match</span>
94	                  <span className="text-4xl font-bold tabular-nums">{r.overall_score?.toFixed(0)}%</span>
95	                </div>
96	                <div className="flex items-center gap-2 pb-1.5">
97	                  <Badge variant={strength.variant} className="shadow-sm">{strength.label}</Badge>
98	                  {r.scoring_version === "heuristic" && <Badge variant="secondary">Quick</Badge>}
99	                  {r.confidence ? <Badge variant="outline" className="text-background/70 border-background/20">{r.confidence}% confidence</Badge> : null}
100	                </div>
101	              </div>
102	
103	              {/* Progress bar */}
104	              <div className="h-1.5 rounded-full bg-background/20 overflow-hidden">
105	                <div className="h-full rounded-full bg-primary transition-all duration-500" style={{ width: `${Math.min(r.overall_score, 100)}%` }} />
106	              </div>
107	            </div>
108	          </div>
109	
110	          {/* Action buttons */}
111	          <div className="px-6 py-3 flex items-center gap-2 border-b border-border shrink-0 bg-muted/30">
112	            {r.candidate_phone && (
113	              <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs"
114	                onClick={() => { navigator.clipboard.writeText(r.candidate_phone!); toast.success("Phone copied!"); }}>
115	                <Phone className="h-3 w-3" /> Call
116	              </Button>
117	            )}
118	            {r.candidate_email && (
119	              <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs"
120	                onClick={() => setEmailDialogOpen(true)}>
121	                <Mail className="h-3 w-3" /> Email
122	              </Button>
123	            )}
124	            {r.file_path && (
125	              <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs"
126	                onClick={() => onDownload(r.file_path!, r.filename)}>
127	                <Download className="h-3 w-3" /> Resume
128	              </Button>
129	            )}
130	            {linkedinUrl && (
131	              <TooltipProvider>
